-- Name: Back click holistic - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH dbs_sl_lands AS ( SELECT mri_session_id, __time FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-13 18:30:00' AND event_name = 'India_sale_load_animation_shown' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' -- LIMIT 20 ), sl_lands AS ( SELECT DISTINCT mri_session_id, __time FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-13 18:30:00' -- AND event_name = 'India_sale_load_animation_shown' AND bu = 'BUS' AND country = 'IND' AND os = 'Android' AND mri_session_id IN (SELECT DISTINCT mri_session_id FROM dbs_sl_lands) -- LIMIT 20 ), back_click AS ( SELECT "__time" AS back_time, "mri_client_id", "mri_session_id", "event_src" FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-13 18:30:00' AND "header_country" = 'IND' AND "event_src" = 'Android' AND "event_group" = 'sl_click_info' AND "event_name" = 'back button tapped' ), Tuples AS ( SELECT DISTINCT srd.mri_session_id AS srpsession, route_id FROM "user_interaction"."search_route_details" srd WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-13 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND total_ratings >= 3.0 AND os = 'Android' -- AND mri_session_id = 'AMaab40f36-fd15-3802-afa5-c06d2cc7d22b' -- AND (src_id, dest_id) IN ((69283, 65782)) -- AND (src_id, dest_id) IN (SELECT source_id, destination_id FROM top_bharat_sds) AND country = 'IND' ), neon_tickets AS ( SELECT t.mri_session_id, t.tin, t.order_uuid, t.route_id, CASE WHEN (t.mri_session_id, t.route_id) IN (SELECT DISTINCT srpsession, route_id FROM Tuples) THEN 'DBS Tuple' ELSE 'non-DBS Tuple' END AS transacted_tuple_type, DATE(date_of_journey) date_of_journey, -- st_name AS stname, date_diff('hour', time_of_event, date_of_journey) AS DBD FROM transaction.bus_ticket_events AS t -- CROSS JOIN -- UNNEST(t.seat_name) AS u (st_name) WHERE date_of_journey >= TIMESTAMP '2026-01-06 18:30:00' AND date_of_journey < TIMESTAMP '2026-01-13 18:30:00' AND country_code = 'IND' and event_type = 101 AND event_class = 2 ), neon_payment AS ( SELECT DISTINCT order_uuid offer_uuid FROM transaction.bus_payment_events WHERE time_of_event >= timestamp '2026-01-06 18:30:00' -- AND time_of_event < timestamp '2026-01-11 18:30:00' AND event_type = 2 AND payment_system_ref_no LIKE ('%DBIND%')AND country_code = 'IND' ) SELECT COUNT(DISTINCT sl.mri_session_id) dbs_sl_lands, COUNT(DISTINCT bc.mri_session_id) back_click_sessions, COUNT(DISTINCT nt.tin) confirmed_tins_offback_button_clicked, COUNT(DISTINCT CASE WHEN transacted_tuple_type = 'non-DBS Tuple' THEN nt.tin END) AS non_DBS_tuple_confirms, COUNT(DISTINCT CASE WHEN transacted_tuple_type = 'DBS Tuple' THEN nt.tin END) AS DBS_tuple_confirms, COUNT(DISTINCT CASE WHEN transacted_tuple_type = 'DBS Tuple' AND np.offer_uuid IS NOT NULL THEN nt.tin END) AS DBS_offer_confirms FROM sl_lands sl LEFT JOIN back_click bc ON bc.mri_session_id = sl.mri_session_id AND sl.__time < bc.back_time LEFT JOIN Tuples t ON t.srpsession = bc.mri_session_id LEFT JOIN neon_tickets nt ON nt.mri_session_id = bc.mri_session_id LEFT JOIN neon_payment np ON np.offer_uuid = nt.order_uuid
